use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTP: one permitted fetch. A transport failure is a value, not a trap,
        // so a feed that is down still lets the heartbeat report. A host outside
        // the allowlist is refused by the host at the boundary.
        let (fetched, fetch_status) = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = body.chars().count();
                (u32::try_from(n).unwrap_or(u32::MAX), String::from("ok"))
            }
            Err(e) => (0u32, format!("error: {}", e)),
        };

        // Notifier: report the heartbeat to the digest channel.
        let message = format!(
            "heartbeat at {}s: fetched {} chars from {} ({})",
            seconds, fetched, feed_url, fetch_status
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // The contract requires `notified == true` on every output. If the
        // channel never accepts the notification, failing the node is the
        // only way to avoid producing an output that violates the contract.
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
